select * from customer; 

--Revenue Analysis
--Compared total revenue generated by male and female customers.

select gender ,sum(purchase_amount) as total_revenue
	from customer
	group by gender;



--Discount & Spending Analysis 
--Identified discount users whose purchase amounts were at or above the overall average.

select customer_id, purchase_amount
	from customer
	where discount_applied = 'Yes'
	and purchase_amount>=(select avg(purchase_amount) from customer);



select * from customer;
--Shipping Analysis — Compared average purchase amounts for Standard and Express shipping.
select shipping_type, round(avg(purchase_amount),2)
from customer
where shipping_type in ('Standard','Express')
group by shipping_type;


--Subscription Analysis —
--Compared customer counts, average spending, and total revenue between subscribers 
--and non-subscribers.

select subscription_status,
	count(customer_id) as total_customers,
	round(avg(purchase_amount),2) as avg_spend,
	round(sum(purchase_amount),2) as total_revenue
		from customer
			group by subscription_status
			order by avg_spend , total_revenue desc;

	
--Discount Dependency Analysis — Identified the top 5 products by percentage of purchases with 
--discounts applied.


select item_purchased,
	round(
			100.0*sum(
						case when Discount_applied = 'Yes' then 1
						else 0 end)/count(*),2,)
						as discount_rate
						from customer
						group by item_purchased
						order by Discount_rate desc
						limit 5;
	)


--Customer Segmentation — Classified customers into New, Returning, and Loyal segments based on previous purchases. 

with customer_type as
	(select customer_id, previous_purchases,
		case when previous_purchases=1 then 'NEW'
			when previous_purchases between 2  then 'Returning'  	
			else 'Loyal'
			end as customer_segmant
			from customer;






--Product Popularity Analysis — Identified the top 3 most purchased products within each category. 
with item_counts as
	(select category,
	item_purchased,
	count(customer_id) as total_order,
	row_number() over (partition by category order by count(customer_id) desc) as item_rank
	from customer
	group by  category, item_purchased
	)
select item_rank, category, item_purchased, total_order
from item_counts
where item_rank<=3; 
--Repeat Buyer Analysis — Compared subscription status among customers with more than 5 previous purchases.

select subscription_status,
count(customer_id) as repeated_buyers
from customer
where previous_purchases>5
group by subscription_status;
--Age Group Revenue Analysis — Compared total revenue across customer age groups.   


select age_group, sum(purchase_amount) as total_revenue
from customer
group by age_group
order by total_revenue desc;